package app.rwun;
import java.time.*;import java.util.*;import org.json.*;
/** Versioned, bounded feature state included in validated training backups. */
final class V103Data {
 static void validate(JSONObject d)throws Exception{
  if(d.has("coaching"))CoachingMemory.validate(d.getJSONObject("coaching"));
  for(String key:V1State.keys(d))if(!Set.of("indoor","activeIndoor","reminders","matches","race","undo","overrides","stepLengths","walks","walkUndo","raceReview","possibleImports","ignoredImports","importOrigins","coaching").contains(key))throw new IllegalArgumentException("Unknown 1.0.3 setting");
  if(d.has("importOrigins")){JSONObject origins=d.getJSONObject("importOrigins");if(origins.length()>20000)throw new IllegalArgumentException("Too many activity origins");for(String id:V1State.keys(origins)){if(id.isEmpty()||id.length()>200)throw new IllegalArgumentException("Invalid activity origin identity");ActivityImportPolicy.validateOrigin(origins.getJSONObject(id));}}
  if(d.has("ignoredImports")){JSONObject ignored=d.getJSONObject("ignoredImports");if(ignored.length()>10000)throw new IllegalArgumentException("Too many ignored imports");for(String id:V1State.keys(ignored))if(id.isEmpty()||id.length()>200||!(ignored.get(id) instanceof Boolean))throw new IllegalArgumentException("Invalid ignored import");}
  if(d.has("possibleImports")){JSONArray queue=d.getJSONArray("possibleImports");if(queue.length()>500)throw new IllegalArgumentException("Too many pending import reviews");Set<String> seen=new HashSet<>();for(int i=0;i<queue.length();i++){JSONObject row=queue.getJSONObject(i);String id=row.getString("id");if(!seen.add(id)||id.length()>200||!(row.get("walk") instanceof Boolean)||row.optString("route").length()>0)throw new IllegalArgumentException("Invalid pending import");ActivityImportPolicy.validateOrigin(row.getJSONObject("origin"));if(row.getBoolean("walk"))WalkData.validate(new JSONArray().put(row));else RunStore.validatePreferences(new JSONObject().put("runs",new JSONArray().put(row).toString()));}}
  if(d.has("raceReview")&&!d.getString("raceReview").matches("[a-f0-9]{64}"))throw new IllegalArgumentException("Invalid race review signature");
  if(d.has("stepLengths")){JSONObject lengths=d.getJSONObject("stepLengths");for(String k:V1State.keys(lengths)){double m=lengths.getDouble(k);if(!Set.of("Walk","Run").contains(k)||!Double.isFinite(m)||m<.2||m>(k.equals("Walk")?1.5:2))throw new IllegalArgumentException("Invalid step calibration");}}
  if(d.has("walks")){if(d.optJSONArray("walks")==null)throw new IllegalArgumentException("Invalid walking history");WalkData.validate(d.getJSONArray("walks"));}if(d.has("walkUndo")){var u=d.getJSONObject("walkUndo");if(u.getLong("expires")<0)throw new IllegalArgumentException("Invalid walk undo");WalkData.validate(new JSONArray().put(u.getJSONObject("walk")));}
  JSONArray rows=d.optJSONArray("indoor");if(d.has("indoor")&&rows==null)throw new IllegalArgumentException("Invalid indoor history");if(rows!=null){if(rows.length()>5000)throw new IllegalArgumentException("Archive indoor history before adding more");Set<String> ids=new HashSet<>();for(int i=0;i<rows.length();i++){var r=rows.getJSONObject(i);String id=r.getString("id");if(!id.matches("[a-zA-Z0-9-]{1,80}")||!ids.add(id)||!Set.of("Walk","Run").contains(r.getString("kind")))throw new IllegalArgumentException("Invalid indoor session");LocalDate.parse(r.getString("date"));whole(r,"seconds",1,180000);if(!r.isNull("km")&&(!Double.isFinite(r.getDouble("km"))||r.getDouble("km")<=0||r.getDouble("km")>250))throw new IllegalArgumentException("Invalid entered distance");whole(r,"effort",1,10);whole(r,"fatigue",1,5);if(r.has("phoneSteps"))whole(r,"phoneSteps",0,1000000);if(r.has("distanceSource")&&!Set.of("Machine entered","Phone steps estimate","Time only","Corrected totals").contains(r.getString("distanceSource")))throw new IllegalArgumentException("Invalid distance source");if(r.has("stepLength")){double m=r.getDouble("stepLength");if(!Double.isFinite(m)||m<0||m>2)throw new IllegalArgumentException("Invalid calibration");}if(r.has("distanceSource")&&r.getString("distanceSource").equals("Phone steps estimate")&&(r.optLong("phoneSteps")<1||r.optDouble("stepLength")<.2||r.isNull("km")))throw new IllegalArgumentException("Missing step estimate evidence");if(!(r.get("pain") instanceof Boolean))throw new IllegalArgumentException("Invalid pain feedback");}}
  if(d.has("activeIndoor")){var a=d.getJSONObject("activeIndoor");if(!a.getString("id").matches("[a-zA-Z0-9-]{1,80}")||!Set.of("Walk","Run").contains(a.getString("kind")))throw new IllegalArgumentException("Invalid active indoor session");LocalDate.parse(a.getString("date"));clock(a);whole(a,"goal",1,180);if(a.has("phoneSteps")&&!(a.get("phoneSteps") instanceof Boolean))throw new IllegalArgumentException("Invalid step consent");if(a.has("phoneStepCount"))whole(a,"phoneStepCount",0,1000000);if(a.has("length")){double m=a.getDouble("length");if(!Double.isFinite(m)||m<0||m>2)throw new IllegalArgumentException("Invalid step length");}}
  if(d.has("reminders")){var r=d.getJSONObject("reminders");plan(r);for(String k:List.of("movement","workouts"))if(!(r.get(k) instanceof Boolean))throw new IllegalArgumentException("Invalid reminder consent");if(r.has("skip")&&!r.getString("skip").isEmpty())LocalDate.parse(r.getString("skip"));if(r.optLong("snooze")<0)throw new IllegalArgumentException("Invalid snooze");if(r.optInt("count")<0||r.optInt("count")>12)throw new IllegalArgumentException("Invalid reminder count");}
  if(d.has("overrides")){var o=d.getJSONObject("overrides");if(o.length()>1000)throw new IllegalArgumentException("Too many schedule changes");for(String key:V1State.keys(o)){var r=o.getJSONObject(key);LocalDate.parse(r.getString("date"));double km=r.getDouble("km"),factor=r.getDouble("factor");if(key.length()>200||!Double.isFinite(km)||km<=0||km>250||!Double.isFinite(factor)||factor<=0||factor>1||r.getString("title").length()>100)throw new IllegalArgumentException("Invalid schedule change");}}
  if(d.has("matches")){JSONObject m=d.getJSONObject("matches");if(m.length()>5000)throw new IllegalArgumentException("Too many matches");Set<String> used=new HashSet<>();for(String k:V1State.keys(m))if(k.length()>200||m.getString(k).length()>200||!used.add(m.getString(k)))throw new IllegalArgumentException("Invalid or duplicate workout match");}
  if(d.has("race")){var r=d.getJSONObject("race");LocalDate.parse(r.getString("date"));if(r.getString("planId").length()>100)throw new IllegalArgumentException("Invalid race identity");for(String key:List.of("name","city","country","surface","source","verified","id"))if(r.has(key)&&(r.getString(key).length()>1000||r.getString(key).trim().isEmpty()))throw new IllegalArgumentException("Invalid race metadata");if(r.has("km")&&(!Double.isFinite(r.getDouble("km"))||r.getDouble("km")<5||r.getDouble("km")>42.2))throw new IllegalArgumentException("Unsupported race distance");}
  if(d.has("undo")){var u=d.getJSONObject("undo");if(u.toString().length()>12000||u.getLong("expires")<0)throw new IllegalArgumentException("Invalid undo record");}
 }
 static void whole(JSONObject d,String k,long low,long high)throws Exception{Object n=d.get(k);if(!(n instanceof Number)||!Double.isFinite(d.getDouble(k))||d.getDouble(k)!=Math.rint(d.getDouble(k))||d.getDouble(k)<low||d.getDouble(k)>high)throw new IllegalArgumentException("Invalid "+k);}
 static IndoorClock clock(JSONObject a)throws Exception{whole(a,"seconds",0,180000);whole(a,"resumed",0,1000000000000000L);return new IndoorClock(a.getLong("seconds"),a.getLong("resumed"),a.getInt("boot"),a.getBoolean("paused"),a.optBoolean("interrupted"));}
 static void clock(JSONObject a,IndoorClock c)throws Exception{a.put("seconds",c.seconds()).put("resumed",c.resumedAt()).put("boot",c.boot()).put("paused",c.paused()).put("interrupted",c.interrupted());}
 static ReminderPlan plan(JSONObject r)throws Exception{for(String k:List.of("start","end","interval","workoutMinute"))whole(r,k,0,1440);Set<Integer> days=new HashSet<>();JSONArray list=r.getJSONArray("days");for(int i=0;i<list.length();i++){Object n=list.get(i);int v=list.getInt(i);if(!(n instanceof Number)||list.getDouble(i)!=v||!days.add(v))throw new IllegalArgumentException("Invalid reminder days");}return new ReminderPlan(r.getBoolean("movement"),r.getBoolean("workouts"),days,r.getInt("start"),r.getInt("end"),r.getInt("interval"),r.getInt("workoutMinute"));}
 static JSONObject reminderDefaults(){try{return new JSONObject().put("movement",false).put("workouts",false).put("days",new JSONArray(List.of(1,2,3,4,5))).put("start",540).put("end",1080).put("interval",60).put("workoutMinute",1080);}catch(Exception e){throw new IllegalStateException(e);}}
 static void sanitiseBackup(JSONObject d)throws Exception{d.remove("activeIndoor");d.remove("undo");d.remove("walkUndo");if(d.has("reminders")){var r=d.getJSONObject("reminders");r.put("movement",false).put("workouts",false);for(String k:List.of("snooze","skip","lastDay","count","lastWorkout"))r.remove(k);}}
}
